  function assetMeta(){return [...S.assets.values()].map(a=>({id:a.id,name:a.name,aliases:a.aliases||[]}));}
  function currentState(){return {config:B.clone(S.config),rawCode:$('editor').value,history:S.history,cursor:S.cursor,revision:S.revision,selected:S.selected,dirty:S.dirty,lastAppliedRaw:S.lastAppliedRaw,pasteDraft:S.pasteDraft,lastInput:S.lastInput,editorMode:$('editor-mode').value};}
  function scheduleSave(){clearTimeout(S.saveTimer);S.saveTimer=setTimeout(async()=>{const snapshot=currentState();try{await B.saveLocal(snapshot,S.assets);setText('save-indicator','已保存在此设备');}catch(error){setText('save-indicator','本次未自动保存 · 可下载项目');$('save-indicator').title=error.message;}},450);}
  function renderDiagnostics(items){const el=$('diagnostics');el.replaceChildren();el.hidden=!items.length;for(const d of items){const b=document.createElement('button');b.textContent=`${d.line}:${d.column} · ${d.message}`;b.title=d.status;b.onclick=()=>{showTab('code');const start=d.start??0;$('editor').focus();$('editor').setSelectionRange(start,Math.max(start+1,d.end??start+1));};el.append(b);}}
  function draw(frame){if(!frame)return;const c=$('canvas');if(c.width!==frame.width){c.width=frame.width;c.height=frame.height;}c.getContext('2d').clearRect(0,0,c.width,c.height);c.getContext('2d').drawImage(frame,0,0);}
  function drawCurrent(){if(!S.result)return;if(S.view==='normalized'){const t=S.result.layers.find(i=>i.layer.id===S.selected)?.texture;if(t?.normalized){draw(t.normalized);return;}}if(S.view==='original'){const asset=S.assets.get(selected()?.assetId);if(asset){const c=B.makeCanvas(768),ctx=c.getContext('2d'),im=asset.image,scale=Math.min(768/im.width,768/im.height);ctx.fillStyle='#f5f0e8';ctx.fillRect(0,0,768,768);ctx.drawImage(im,(768-im.width*scale)/2,(768-im.height*scale)/2,im.width*scale,im.height*scale);draw(c);return;}}draw(B.composeFrame(S.result,S.config,S.progress));}
  function stopAnimation(){S.playing=false;cancelAnimationFrame(S.frameId);$('play').innerHTML=icon('play');$('play').setAttribute('aria-label','播放动画');}
  function updateProgress(){ $('progress').value=Math.round(S.progress*1000);setText('progress-label',Math.round(S.progress*100)+'%');if($('time-label')){const total=S.config.global.duration/(S.config.global.speed/5);setText('time-label',(S.progress*total).toFixed(1)+' / '+total.toFixed(1)+'s');}}
  function animate(time){if(!S.playing)return;const dt=Math.min(100,time-S.lastTick);S.lastTick=time;S.progress+=dt/(S.config.global.duration*1000/(S.config.global.speed/5));if(S.progress>=1){if(S.config.global.loop)S.progress%=1;else{S.progress=1;stopAnimation();}}drawCurrent();updateProgress();if(S.playing)S.frameId=requestAnimationFrame(animate);}
  function togglePlay(){if(!S.result||S.config.global.animation==='无')return;if(S.playing){stopAnimation();return;}if(S.config.global.animation==='图案融合'&&S.config.layers.filter(l=>l.visible!==false).length<2){toast('图案融合动画需要至少两个可见图层。');return;}S.view='final';$('canvas-wrap').dataset.view='';S.refreshControls?.();if(S.progress>=1)S.progress=0;S.playing=true;S.lastTick=performance.now();$('play').innerHTML=icon('pause');$('play').setAttribute('aria-label','暂停动画');S.frameId=requestAnimationFrame(animate);}
  function record(label){const snapshot={id:crypto.randomUUID?.()||String(Date.now()),time:new Date().toISOString(),label,config:B.clone(S.config),rawCode:$('editor').value,selected:S.selected,pasteDraft:S.pasteDraft,lastInput:B.clone(S.lastInput),editorMode:$('editor-mode').value};if(S.cursor>=0&&JSON.stringify(S.history[S.cursor]?.config)===JSON.stringify(snapshot.config))return;S.history=S.history.slice(0,S.cursor+1);S.history.push(snapshot);if(S.history.length>B.LIMITS.history)S.history.shift();S.cursor=S.history.length-1;}
  async function commit(config,{rawCode,fromEditor=false,label='更新作品',diagnostics=[],noHistory=false,force=false}={}){
    stopAnimation();S.pendingConfig=config;S.controller?.abort();S.controller=new AbortController();const controller=S.controller,job=++S.job,editorAtStart=$('editor').value;clearTimeout(busyTimer);$('busy').hidden=true;busyTimer=setTimeout(()=>{if(job===S.job){$('busy').hidden=false;setText('busy-text','正在染制…');}},650);
    try{
      const oldFrames=new Map((S.result?.layers||[]).map(l=>[l.layer.id,l]));
      const result=await B.renderCandidate(config,S.assets,{signal:controller.signal,size:S.previewSize,previousLayers:oldFrames,onProgress:p=>setText('busy-text',`正在染制 ${Math.round(p*100)}%`)});
      if(job!==S.job||controller.signal.aborted)return false;
      const changed=JSON.stringify(S.config)!==JSON.stringify(config);stopAnimation();S.config=config;S.pendingConfig=null;S.result=result;S.revision+=changed?1:0;if(result.duration>300)S.previewSize=512;
      if(!S.config.layers.some(l=>l.id===S.selected))S.selected=S.config.layers.at(-1)?.id||null;
      if(fromEditor){S.lastAppliedRaw=rawCode;S.dirty=$('editor').value!==editorAtStart;}else if(!S.dirty){setEditor(B.toCode(S.config));S.lastAppliedRaw=$('editor').value;}
      drawCurrent();updateProgress();const all=[...diagnostics,...result.diagnostics];renderDiagnostics(all);
      const skipped=all.filter(d=>d.status==='已跳过').length,adjusted=all.filter(d=>d.status!=='已跳过').length;
      setStatus(skipped?`部分应用 · ${skipped} 处待处理`:adjusted?`已调整 ${adjusted} 处`:'已应用',skipped?'warning':'success');
      if(fromEditor&&skipped)S.dirty=true;
      if((changed||force)&&!noHistory)record(label);updateUI();scheduleSave();return true;
    }catch(error){if(error.name!=='AbortError'){setStatus('保留现有作品','warning');toast('本次染制未完成，成功作品已保留。'+error.message);}return false;}
    finally{if(job===S.job){S.pendingConfig=null;clearTimeout(busyTimer);$('busy').hidden=true;}}
  }
  async function applySource(code,mode='patch',options={}){
    S.lastInput={code,mode,time:new Date().toISOString(),source:options.fromEditor?'editor':options.label||'local'};
    const parsed=B.parseAndRecover(code,{baseConfig:S.pendingConfig||S.config,mode,targetLayerId:S.selected,assets:assetMeta(),operationId:options.operationId,fullProject:options.fullProject});
    if(parsed.choices){openPaste(code);previewPaste();return false;}
    if(!parsed.applied){renderDiagnostics(parsed.diagnostics);setStatus('未应用新变更 · 保留作品','warning');scheduleSave();return false;}
    if(single&&parsed.config.layers.length>1){setStatus('单图入口最多一层','warning');toast('多图代码请在创作工坊入口使用。');return false;}
    return commit(parsed.config,{rawCode:code,fromEditor:options.fromEditor,label:options.label||'应用中文代码',diagnostics:parsed.diagnostics});
  }
  async function patchLayer(code,label){return applySource(code,'patch',{label});}
  async function editConfig(mutator,label){const candidate=B.clone(S.pendingConfig||S.config);mutator(candidate);return applySource(B.toCode(candidate),'replace',{label,fullProject:true});}
  function showTab(name){for(const n of ['code','manual','history']){$('panel-'+n).hidden=n!==name;$('tab-'+n).setAttribute('aria-selected',String(n===name));}if(name==='history')renderHistory();}
  function addOptions(el,values){for(const value of values){const o=document.createElement('option');o.value=value;o.textContent=value;el.append(o);}}
  addOptions($('blend'),B.BLENDS);addOptions($('animation'),B.ANIMATIONS);addOptions($('background'),Object.keys(B.BACKGROUNDS));addOptions($('overlay-color'),Object.keys(B.COLORS));$('overlay-color').value='黄';
  function makeSlider(key,container){const p=B.PARAMS[key],wrap=document.createElement('div');wrap.className='range-control';const top=document.createElement('div');top.className='range-top';const label=document.createElement('label');label.htmlFor='param-'+key;label.textContent=p.label;label.title=p.note||'';const out=document.createElement('output');out.id='out-'+key;top.append(label,out);const input=document.createElement('input');Object.assign(input,{type:'range',id:'param-'+key,min:p.min,max:p.max,step:p.step});input.dataset.param=key;input.addEventListener('input',()=>out.textContent=B.numberText(Number(input.value)));input.addEventListener('change',()=>patchLayer(`${p.l2}: ${B.numberText(Number(input.value)*p.divisor)};`,'调整'+p.label));wrap.append(top,input);$(container).append(wrap);}
  for(const k of ['dyeDepth','crackDensity','crackWidth'])makeSlider(k,'primary-controls');for(const k of ['droplets','stroke','halo','grain'])makeSlider(k,'extra-controls');makeSlider('opacity','opacity-control');
  for(const [k,label] of Object.entries({x:'横向位置',y:'纵向位置',width:'宽度',height:'高度',rotation:'旋转角度'})){const wrap=document.createElement('div');wrap.className='field';const l=document.createElement('label');l.textContent=label;l.htmlFor='transform-'+k;const input=document.createElement('input');input.type='number';input.id='transform-'+k;input.dataset.transform=k;input.step=1;input.addEventListener('change',()=>{const val=Number(input.value);if(!Number.isFinite(val))return;const obj=selected();if(!obj)return;const code=k==='rotation'?`旋转: ${val};`:['x','y'].includes(k)?`位置: ${k==='x'?val:obj.x}, ${k==='y'?val:obj.y};`:`大小: ${k==='width'?val:obj.width}, ${k==='height'?val:obj.height};`;patchLayer(code,'调整图层变换');});wrap.append(l,input);$('transforms').append(wrap);}
  for(const [name,hex] of Object.entries(B.COLORS)){const button=document.createElement('button');button.className='swatch';button.style.backgroundColor=hex;button.title=name;button.setAttribute('aria-label','染色 '+name);button.dataset.color=name;$('swatches').append(button);}
  function renderLayers(){const list=$('layers');list.replaceChildren();for(const l of [...S.config.layers].reverse()){const a=S.assets.get(l.assetId),row=document.createElement('div');row.className='layer-item'+(l.id===S.selected?' selected':'');const button=document.createElement('button');button.className='layer-select';button.setAttribute('aria-label','选择'+l.id);const img=document.createElement('canvas');img.width=60;img.height=60;img.className='layer-thumb';const frame=S.result?.layers.find(item=>item.layer.id===l.id);if(frame){img.getContext('2d').drawImage(frame.texture.base,0,0,60,60);img.getContext('2d').drawImage(frame.texture.crack,0,0,60,60);}const text=document.createElement('span');text.className='layer-name';const title=document.createElement('strong');title.textContent=a?.name||'缺少素材';const sub=document.createElement('small');sub.textContent=l.id+' · '+(a?'已关联':'请重新关联');text.append(title,sub);button.append(img,text);button.onclick=()=>{S.selected=l.id;drawCurrent();updateUI();scheduleSave();};const more=document.createElement('button');more.className='icon-btn';more.innerHTML=icon('more');more.setAttribute('aria-label',l.id+'更多操作');more.onclick=e=>{e.stopPropagation();S.selected=l.id;updateUI();openContext(e.clientX,e.clientY);};row.append(button,more);list.append(row);}}
  function renderHistory(){const panel=$('panel-history');panel.replaceChildren();if(!S.history.length){const p=document.createElement('p');p.className='history-empty';p.textContent='成功应用后的作品会记录在这里，最多保留 50 个版本。草稿另行自动保存。';panel.append(p);return;}[...S.history].reverse().forEach((h,reversed)=>{const index=S.history.length-1-reversed,row=document.createElement('div');row.className='history-item';const text=document.createElement('div');text.className='history-info';const title=document.createElement('strong');title.textContent=(index===S.cursor?'● ':'')+h.label;const time=document.createElement('small');time.textContent=new Date(h.time).toLocaleString('zh-CN',{hour12:false})+' · '+h.config.layers.length+' 图层';text.append(title,time);const button=document.createElement('button');button.className='btn';button.textContent='恢复';button.onclick=()=>restoreHistory(index);row.append(text,button);panel.append(row);});}
  function updateSelection(){const l=selected(),el=$('selection');el.hidden=!l||!S.result?.layers.some(i=>i.layer.id===l.id);if(!l)return;el.style.left=(l.x/1024*100)+'%';el.style.top=(l.y/1024*100)+'%';el.style.width=(l.width/1024*100)+'%';el.style.height=(l.height/1024*100)+'%';el.style.transform=`rotate(${l.rotation}deg)`;}
  function updateUI(){
    const l=selected(),count=S.config.layers.length,g=S.config.global;
    setText('layer-count',count+'/'+(single?1:3));setText('inspector-count',count+' / '+(single?1:3));$('empty').hidden=count>0;$('canvas-wrap').hidden=count===0;$('canvas-tools').hidden=!l;$('export-png').disabled=!S.result?.layers.length;$('undo').disabled=S.cursor<=0;$('redo').disabled=S.cursor>=S.history.length-1;
    setText('art-name',l?(S.assets.get(l.assetId)?.name.replace(/\.[^.]+$/,'')||'待关联素材'):'未命名作品');setText('art-style',l?l.style+'蜡染':'中式蜡染');setText('preview-mode',l?.orientation||'等待一幅图案');setText('dimensions',`${g.outputSize} × ${g.outputSize} px`);setText('revision-label',S.revision?' · v'+S.revision:'');
    renderLayers();updateSelection();
    for(const input of document.querySelectorAll('[data-param]')){const key=input.dataset.param;input.disabled=!l;if(l&&document.activeElement!==input){input.value=l[key];setText('out-'+key,B.numberText(l[key]));}}
    for(const input of document.querySelectorAll('[data-transform]')){input.disabled=!l;if(l&&document.activeElement!==input)input.value=B.numberText(l[input.dataset.transform]);}
    for(const button of document.querySelectorAll('[data-color]')){button.disabled=!l;button.classList.toggle('active',l?.mainColor===button.dataset.color);button.setAttribute('aria-pressed',String(l?.mainColor===button.dataset.color));}
    for(const button of document.querySelectorAll('[data-style]')){button.disabled=!l;button.classList.toggle('active',l?.style===button.dataset.style);}
    for(const button of document.querySelectorAll('[data-orientation]')){button.disabled=!l;button.classList.toggle('active',l?.orientation===button.dataset.orientation);}
    $('blend').disabled=!l;$('blend').value=l?.blend||'叠印';$('seed').disabled=!l;$('seed').value=l?.seed??2026;$('preset').disabled=!l;$('background').value=g.background;$('animation').value=g.animation;$('speed').value=g.speed;$('loop').checked=g.loop;$('animation-bar').hidden=g.animation==='无'||!count;setText('animation-name',g.animation);
    $('asset-select').replaceChildren();addOptions($('asset-select'),[...S.assets.keys()]);for(const option of $('asset-select').options)option.textContent=option.value+' · '+S.assets.get(option.value).name;$('asset-select').value=l?.assetId||'';$('asset-select').disabled=!l;
    renderHistory();S.refreshControls?.();
  }
  async function restoreHistory(index){const h=S.history[index];if(!h)return;S.controller?.abort();S.pendingConfig=null;S.revision++;const previous=currentState(),draft=S.dirty?$('editor').value:null;setEditor(h.rawCode||B.toCode(h.config));S.selected=h.selected;S.pasteDraft=h.pasteDraft||'';S.lastInput=h.lastInput||null;$('editor-mode').value=h.editorMode||'replace';const ok=await commit(B.clone(h.config),{noHistory:true,fromEditor:true,rawCode:$('editor').value});if(ok){S.cursor=index;if(draft!==null&&!S.dirty)setEditor(draft,{dirty:true});updateUI();scheduleSave();toast('已恢复该版本');}else if(!S.dirty){setEditor(previous.rawCode,{dirty:previous.dirty});S.selected=previous.selected;}}
  function makeAssetId(){let id;do{id='图片'+(++assetSequence);}while(S.assets.has(id));return id;}
  async function registerBlob(blob,name,{id,aliases=[]}={}){const asset=await B.decodeAsset(blob,{id:id||makeAssetId(),name,aliases});S.assets.set(asset.id,asset);return asset;}
  async function addAssetLayer(asset){const max=single?1:3;if(S.config.layers.length>=max){toast(single?'单图入口仅支持一层，请在图层中重新关联素材。':'最多 3 个图层，请先删除或重新关联一层。');return false;}const n=[1,2,3].find(i=>!S.config.layers.some(l=>l.id==='图层'+i)),layer=B.defaults('图层'+n,asset.id);S.selected=layer.id;return editConfig(c=>c.layers.push(layer),'添加 '+asset.name);}
  async function loadDemo(name,{initial=false}={}){
    try{if(S.config.layers.length>=(single?1:3)){toast('图层已满，可在素材关联中更换图片。');return;}const key='示例-'+name;let asset=S.assets.get(key);if(!asset){const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=assetURL(name+'.svg');});const c=B.makeCanvas(1024);c.getContext('2d').drawImage(image,0,0,1024,1024);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));asset=await registerBlob(blob,name==='spiral'?'织金螺旋几何纹':'丹寨花鸟纹',{id:key,aliases:[name==='spiral'?'几何示例':'花鸟示例']});}await addAssetLayer(asset);if(initial)toast('已铺开花鸟纹示例，可以直接调整或上传你的图片。');}catch(error){toast('示例未能读取，请上传图片继续创作。');}
  }
  async function uploadFiles(files,{relink=false}={}){const list=[...files];if(!list.length)return;const cap=(single?1:3)-S.config.layers.length;if(!relink&&cap<=0){toast('图层已满，请先删除或重新关联图片。');return;}if(!relink&&list.length>cap)toast('最多保留 '+(single?1:3)+' 个图层，已处理可用名额。');for(const file of list.slice(0,relink?1:cap)){if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('支持 PNG、JPG 和 WebP 图片。');continue;}try{const a=await registerBlob(file,file.name);if(relink&&selected())await patchLayer('素材: '+JSON.stringify(a.id)+';','重新关联素材');else await addAssetLayer(a);}catch(error){toast(file.name+'：'+error.message);}}}
  function openPaste(code=S.pasteDraft||''){$('paste-code').value=code;$('paste-preview').hidden=true;$('code-choices').replaceChildren();$('apply-paste').disabled=false;if(!$('code-dialog').open)$('code-dialog').showModal();}
  function previewPaste(){const code=$('paste-code').value,r=B.parseAndRecover(code,{baseConfig:S.config,mode:$('paste-mode').value,targetLayerId:S.selected,assets:assetMeta()});const box=$('paste-preview');box.hidden=false;box.replaceChildren();const p=document.createElement('p');p.textContent=r.choices?'检测到多个备选方案，请选择一个：':!r.applied?'没有可应用的中文代码，保留现有作品。':`${r.status} · ${r.applied} 项赋值；${r.diagnostics.length} 条修正或跳过记录。`;box.append(p);for(const d of r.diagnostics){const item=document.createElement('div');item.textContent=`${d.line}:${d.column} · ${d.message}`;box.append(item);}$('apply-paste').disabled=!r.applied;$('code-choices').replaceChildren();if(r.choices)for(const [i,choice] of r.choices.entries()){const button=document.createElement('button');button.className='choice-btn';button.textContent='选择方案 '+(i+1)+'\n'+choice.code;button.onclick=()=>{$('paste-code').value=choice.code;previewPaste();};$('code-choices').append(button);}return r;}
  async function copyText(text){try{await navigator.clipboard.writeText(text);toast('代码已复制');}catch(error){const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'代码已复制':'请在代码框中全选复制。');}}
  function download(blob,name){if(!blob)throw new Error('没有可下载的文件。');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function dateName(){return new Date().toISOString().slice(0,10)+'-'+String(S.revision).padStart(3,'0');}
  async function exportProject(){try{setText('save-indicator','正在打包项目…');const text=await B.exportProject(currentState(),S.assets);download(new Blob([text],{type:'application/json'}),'蜡染-'+dateName()+'.batik-project.json');setText('save-indicator','项目已导出');toast('完整项目已下载，包含素材、草稿与历史。');}catch(error){toast('项目未能导出，当前作品已保留。'+error.message);}}
  function openPng(capture=false){if(!S.result?.layers.length){toast('请先添加可用的图片。');return;}$('png-current').checked=capture;if(![...$('png-size').options].some(o=>Number(o.value)===S.config.global.outputSize)){const option=document.createElement('option');option.value=S.config.global.outputSize;option.textContent=S.config.global.outputSize+' × '+S.config.global.outputSize;$('png-size').append(option);}$('png-size').value=String(S.config.global.outputSize);setText('png-description',`导出成功版本 v${S.revision}，按目标尺寸重新计算。未应用草稿不影响本次导出。`);setText('png-status','');$('png-dialog').showModal();}
  async function downloadPng(){
    if(S.exportController)return;const controller=S.exportController=new AbortController(),config=B.clone(S.config),revision=S.revision,progress=S.progress,current=$('png-current').checked;config.global.outputSize=Number($('png-size').value);$('png-download').disabled=true;$('png-cancel').hidden=false;setText('png-status','正在按导出尺寸染制，可随时取消…');
    try{const result=await B.renderCandidate(config,S.assets,{size:config.global.outputSize,signal:controller.signal,onProgress:p=>setText('png-status','正在染制 '+Math.round(p*100)+'%')});if(result.diagnostics.length)throw new Error('部分图层无法导出，请先重新关联素材。');const frame=current?B.composeFrame(result,config,progress):result.frame;const blob=await new Promise((resolve,reject)=>{try{frame.toBlob(b=>b?resolve(b):reject(new Error('PNG 编码失败。')),'image/png');}catch(e){reject(e);}});if(controller.signal.aborted)throw new DOMException('已取消','AbortError');download(blob,`蜡染-v${revision}-${config.global.outputSize}${current?'-截帧':''}.png`);setText('png-status','已下载 PNG · v'+revision);toast('PNG 已下载');}catch(error){setText('png-status',error.name==='AbortError'?'已取消，作品已保留。':'导出未完成，作品已保留。'+error.message);}finally{S.exportController=null;$('png-download').disabled=false;$('png-cancel').hidden=true;}
  }
  async function importFile(file){try{if(file.name.endsWith('.batik-project.json')||file.name.endsWith('.json')){const imported=await B.importProject(file);S.controller?.abort();const previous={assets:S.assets,...currentState()};B.clearRenderCache();S.assets=imported.assets;S.selected=imported.state.selected;setEditor(imported.state.rawCode,{dirty:!!imported.state.dirty});const ok=await commit(imported.state.config,{noHistory:true,diagnostics:imported.diagnostics});if(!ok){S.assets=previous.assets;setEditor(previous.rawCode,{dirty:previous.dirty});S.selected=previous.selected;return;}S.history=imported.state.history;S.cursor=Math.min(S.history.length-1,Math.max(0,imported.state.cursor??S.history.length-1));S.lastAppliedRaw=imported.state.lastAppliedRaw||'';S.pasteDraft=imported.state.pasteDraft||'';S.lastInput=imported.state.lastInput||null;$('editor-mode').value=imported.state.editorMode||'replace';if(!S.history.length)record('导入项目');setEditor(imported.state.rawCode,{dirty:!!imported.state.dirty});updateUI();scheduleSave();toast('完整项目已恢复');}else{if(file.size>B.LIMITS.codeBytes)throw new Error('代码超过 100 KiB。');const code=(await file.text()).replace(/^\uFEFF/,'');setEditor(code,{dirty:true});showTab('code');if(!/^# BatikScript/.test(code))toast('旧代码采用文档的 L1/L2 兼容映射；请核对预览。');await applySource(code,'replace',{fromEditor:true,label:'导入代码'});}}catch(error){toast('导入未完成，原作品已保留。'+error.message);}}
