  function rememberText(force=false,before=S.editorValue){const now=Date.now();if(before!==$('editor').value){if(force||!S.textTime||now-S.textTime>500)S.textPast.push({code:before,start:$('editor').selectionStart,end:$('editor').selectionEnd});S.textFuture=[];S.textTime=force?0:now;S.editorValue=$('editor').value;}}
  function undoText(redo=false){clearTimeout(editTimer);S.controller?.abort();S.pendingConfig=null;S.job++;const from=redo?S.textFuture:S.textPast,to=redo?S.textPast:S.textFuture,item=from.pop();if(!item)return;to.push({code:$('editor').value,start:$('editor').selectionStart,end:$('editor').selectionEnd});setEditor(item.code,{dirty:true});$('editor').setSelectionRange(item.start,item.end);S.textTime=0;scheduleSave();setStatus('文本已恢复 · 可手动应用');}
